// Renueva el token de LinkedIn de cada empresa antes de que venza. LinkedIn da tokens de
// publicación por 60 días como máximo; el refresh token (1 año) sirve para pedir uno nuevo sin
// entrar a LinkedIn. Por cada empresa del Config: lee el token guardado en G54
// (GET /api/rrss/tokens) y, si le faltan menos de DIAS_ANTES días, pide uno nuevo a LinkedIn y
// lo guarda en G54 (PUT /api/rrss/tokens) con su fecha de vencimiento.
// Por el webhook: dry_run solo informa sin renovar; forzar renueva aunque falten más días.
const cfg = $('⚙️ Config Renovación LinkedIn').first().json;
const entrada = cfg._entrada || {};
const dryRun = entrada.dry_run === true || entrada.dry_run === 'true';
const forzar = entrada.forzar === true || entrada.forzar === 'true';
const http = (o) => this.helpers.httpRequest({ json: true, timeout: 30000, ...o });
const G = cfg.G54_BASE_URL + '/api';
const empresas = JSON.parse(cfg.EMPRESAS_JSON || '[]');
// Si LinkedIn devolvió un refresh token nuevo en una corrida anterior, se usa ese.
const memoria = $getWorkflowStaticData('global');
memoria.refresh = memoria.refresh || {};
const resultados = [];
const login = await http({ method: 'POST', url: G + '/auth/login', body: { email: cfg.G54_MASTER_EMAIL, password: cfg.G54_MASTER_PASSWORD } });
const auth = { Authorization: 'Bearer ' + (login.access_token || login.token), Accept: 'application/json' };
try {
  for (const emp of empresas) {
    const r = { company_id: emp.company_id };
    try {
      await http({ method: 'POST', url: G + '/auth/switch-company', headers: auth, body: { company_id: emp.company_id } });
      const lista = await http({ method: 'GET', url: G + '/rrss/tokens', headers: auth });
      const fila = (lista.data || lista || []).find((x) => String(x.platform || '').toLowerCase() === 'linkedin');
      if (!fila) { r.estado = 'sin_token_linkedin_en_g54'; resultados.push(r); continue; }
      r.page_id = fila.page_id;
      r.vence_antes = fila.expires_at;
      const dias = fila.expires_at ? (new Date(fila.expires_at) - Date.now()) / 86400000 : 0;
      r.dias_restantes = Math.round(dias);
      if (!forzar && dias > Number(cfg.DIAS_ANTES)) { r.estado = 'vigente'; resultados.push(r); continue; }
      if (dryRun) { r.estado = 'se_renovaria'; resultados.push(r); continue; }
      const refresh = memoria.refresh[emp.company_id] || emp.refresh_token;
      // n8n no tiene URLSearchParams en el Code node: el formulario se arma a mano.
      const form = Object.entries({ grant_type: 'refresh_token', refresh_token: refresh, client_id: cfg.LINKEDIN_CLIENT_ID, client_secret: cfg.LINKEDIN_CLIENT_SECRET })
        .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
      const crudo = await http({ method: 'POST', url: 'https://www.linkedin.com/oauth/v2/accessToken', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: form, json: false });
      const j = typeof crudo === 'string' ? JSON.parse(crudo) : crudo;
      if (!j.access_token) throw new Error('LinkedIn no devolvió token: ' + JSON.stringify(j).slice(0, 200));
      if (j.refresh_token && j.refresh_token !== refresh) memoria.refresh[emp.company_id] = j.refresh_token;
      const vence = new Date(Date.now() + (Number(j.expires_in) || 5184000) * 1000).toISOString().slice(0, 10);
      await http({ method: 'PUT', url: G + '/rrss/tokens', headers: auth, body: { platform: fila.platform, access_token: j.access_token, page_id: fila.page_id, instagram_account_id: fila.instagram_account_id || '', label: fila.label || '', expires_at: vence } });
      r.estado = 'renovado';
      r.vence_ahora = vence;
      if (j.refresh_token_expires_in) r.refresh_vence = new Date(Date.now() + Number(j.refresh_token_expires_in) * 1000).toISOString().slice(0, 10);
    } catch (e) {
      r.estado = 'error';
      r.error = String(e.message || e).slice(0, 300);
    }
    resultados.push(r);
  }
} finally {
  try { await http({ method: 'POST', url: G + '/auth/logout', headers: auth, body: {} }); } catch (e) {}
}
return [{ json: { ok: !resultados.some((x) => x.estado === 'error'), dry_run: dryRun, resultados } }];
